import java.util.*;class Solution{public int calculate(String s){Deque<Integer>st=new ArrayDeque<>();int r=0,n=0,sg=1;for(int i=0;i<=s.length();i++){char c=i<s.length()?s.charAt(i):0;if(Character.isDigit(c))n=n*10+c-'0';else if(c=='+'||c=='-'){r+=sg*n;n=0;sg=c=='+'?1:-1;}else if(c=='('){st.push(r);st.push(sg);r=0;sg=1;}else if(c==')'){r+=sg*n;n=0;r=st.pop()*r+st.pop();}else if(c==0)r+=sg*n;}return r;}}
